       @Monad.Eq1Equivalence T MT QT ->
       @Monad.Eq1Equivalence (ReaderMonad.readerT Env T) (@ReaderMonad.Monad_readerT Env T MT)
         (@ReaderT.readerT_eq1 Env T QT)

@ReaderT.readerT_monad_laws
     : forall (Env : Type) (T : Type -> Type) (MT : Monad.Monad T) (QT : Monad.Eq1 T),
       @Monad.MonadLawsE T QT MT ->
       @Monad.MonadLawsE (ReaderMonad.readerT Env T) (@ReaderT.readerT_eq1 Env T QT)
         (@ReaderMonad.Monad_readerT Env T MT)

@ReaderT.readerT_iteration_uniform
     : forall (Env : Type) (T : Type -> Type) (MT : Monad.Monad T) (QT : Monad.Eq1 T)
         (IT : Basics.MonadIter T),
       @IterationLaws.iteration_uniform T MT IT QT ->
       @IterationLaws.iteration_uniform (ReaderMonad.readerT Env T)
         (@ReaderMonad.Monad_readerT Env T MT) (@Basics.MonadIter_readerT T Env IT)
         (@ReaderT.readerT_eq1 Env T QT)

@WriterT.writerT_monad
     : forall (W : Type) (T : Type -> Type),
       Monoid.Monoid W -> Monad.Monad T -> Monad.Monad (Basics.Monads.writerT W T)

@WriterT.writerT_eq_equivalence
     : forall (W : Type) (T : Type -> Type) (op : Monoid.Monoid W) (MT : Monad.Monad T)
         (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.Eq1Equivalence (Basics.Monads.writerT W T) (@WriterT.writerT_monad W T op MT)
         (@WriterT.writerT_eq1 W T QT)

@WriterT.writerT_monad_laws
     : forall (W : Type) (T : Type -> Type) (op : Monoid.Monoid W) (MT : Monad.Monad T)
         (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       @Monoid.MonoidLaws W op ->
       @Monad.MonadLawsE (Basics.Monads.writerT W T) (@WriterT.writerT_eq1 W T QT)
