@WriterT.writerT_iteration_uniform
     : forall (W : Type) (T : Type -> Type) (op : Monoid.Monoid W) (MT : Monad.Monad T)
         (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       @Monoid.MonoidLaws W op ->
       forall IT : Basics.MonadIter T,
       @IterationLaws.iteration_uniform T MT IT QT ->
       @IterationLaws.iteration_uniform (Basics.Monads.writerT W T)
         (@WriterT.writerT_monad W T op MT) (@WriterT.writerT_iter W T op MT IT)
         (@WriterT.writerT_eq1 W T QT)

@FoldITree.itree_strong_equivalence
     : forall F : Type -> Type,
       @Monad.Eq1Equivalence (ITreeDefinition.itree F) (@ITreeDefinition.Monad_itree F)
         (@FoldITree.itree_strong_eq1 F)

@FoldITree.itree_strong_monad_laws
     : forall F : Type -> Type,
       @Monad.MonadLawsE (ITreeDefinition.itree F) (@FoldITree.itree_strong_eq1 F)
         (@ITreeDefinition.Monad_itree F)

@FoldITree.itree_fold_observe_eq
     : forall (E MN F : Type -> Type) (handle : forall X : Type, E X -> ITreeDefinition.itree F X)
         (sample : forall X : Type, MN X -> ITreeDefinition.itree F X)
         (A : Type) (t u : PTreeDefinition.ptree E MN A),
       @PTreeDefinition.observe E MN A t = @PTreeDefinition.observe E MN A u ->
       @Eqit.eq_itree F A A (@eq A)
         (@Fold.fold E MN (ITreeDefinition.itree F) (@ITreeDefinition.Monad_itree F)
            (@ITreeDefinition.MonadIter_itree F) handle sample A t)
         (@Fold.fold E MN (ITreeDefinition.itree F) (@ITreeDefinition.Monad_itree F)
            (@ITreeDefinition.MonadIter_itree F) handle sample A u)

@ReaderFold.reader_sample
     : forall (Env : Type) (MN T : Type -> Type),
       (forall X : Type, MN X -> T X) -> forall X : Type, MN X -> ReaderMonad.readerT Env T X

@ReaderFold.fold_reader_as_iter
     : forall (Env : Type) (E MN T : Type -> Type) (MT : Monad.Monad T)
         (IT : Basics.MonadIter T) (handle : forall X : Type, E X -> T X)
         (sample : forall X : Type, MN X -> T X) (A : Type)
         (t : PTreeDefinition.ptree (Sum.sum1 (Reader.readerE Env) E) MN A)
         (env : Env),
       @ReaderFold.fold_reader Env E MN T MT IT handle sample A t env =
       @Basics.iter T IT A (PTreeDefinition.ptree (Sum.sum1 (Reader.readerE Env) E) MN A)
         (@ReaderFold.reader_fold_step Env E MN T MT handle sample A env) t

@ReaderFold.reader_sample_independent
     : forall (Env : Type) (MN T : Type -> Type) (sample : forall X : Type, MN X -> T X)
         (X : Type) (mu : MN X) (env : Env),
       @ReaderMonad.runReaderT Env T X (@ReaderFold.reader_sample Env MN T sample X mu) env =
       sample X mu

@WriterFold.fold_writer_as_iter
     : forall (W : Type) (E MN T : Type -> Type) (op : Monoid.Monoid W)
         (MT : Monad.Monad T) (IT : Basics.MonadIter T) (handle : forall X : Type, E X -> T X)
         (sample : forall X : Type, MN X -> T X) (A : Type)
         (t : PTreeDefinition.ptree (Sum.sum1 (Writer.writerE W) E) MN A),
       @WriterFold.fold_writer W E MN T op MT IT handle sample A t =
       @Basics.iter T IT (W * A) (W * PTreeDefinition.ptree (Sum.sum1 (Writer.writerE W) E) MN A)
         (@WriterFold.writer_fold_step W E MN T op MT handle sample A)
         (@Monoid.monoid_unit W op, t)

@WriterFold.writer_sample_empty_log
     : forall (W : Type) (MN T : Type -> Type) (op : Monoid.Monoid W) (MT : Monad.Monad T)
         (sample : forall X : Type, MN X -> T X) (X : Type) (mu : MN X),
       @WriterFold.writer_sample W MN T op MT sample X mu =
       @Monad.bind T MT X (W * X) (sample X mu)
         (fun x : X => @Monad.ret T MT (W * X) (@Monoid.monoid_unit W op, x))

@WriterFoldFacts.writer_fold_step_normalize
     : forall (W : Type) (E MN T : Type -> Type) (op : Monoid.Monoid W)
         (MT : Monad.Monad T) (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       @Monoid.MonoidLaws W op ->
       forall (handle : forall X : Type, E X -> T X) (sample : forall X : Type, MN X -> T X)
         (A : Type) (t : PTreeDefinition.ptree (Sum.sum1 (Writer.writerE W) E) MN A)
         (log : W),
       @Monad.eq1 T QT (W * PTreeDefinition.ptree (Sum.sum1 (Writer.writerE W) E) MN A + W * A)
         (@WriterFold.writer_fold_step W E MN T op MT handle sample A (log, t))
         (@WriterFoldFacts.writer_next W E MN T op MT handle sample A log t)

@WriterFoldITree.itree_writer_fold_ret
     : forall (W : Type) (E MN F : Type -> Type) (op : Monoid.Monoid W),
       @Monoid.MonoidLaws W op ->
       forall (handle : forall X : Type, E X -> ITreeDefinition.itree F X)
         (sample : forall X : Type, MN X -> ITreeDefinition.itree F X)
         (A : Type) (a : A),
       @Eqit.eq_itree F (W * A) (W * A) (@eq (W * A))
         (@WriterFold.fold_writer W E MN (ITreeDefinition.itree F) op
            (@ITreeDefinition.Monad_itree F) (@ITreeDefinition.MonadIter_itree F) handle sample A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.RetF (Sum.sum1 (Writer.writerE W) E) MN A
                  (PTreeDefinition.ptree (Sum.sum1 (Writer.writerE W) E) MN A) a
            |})
         {|
           ITreeDefinition._observe :=
             @ITreeDefinition.RetF F (W * A) (ITreeDefinition.itree F (W * A))
               (@Monoid.monoid_unit W op, a)
         |}

@ReaderWriterFold.reader_target_monad
     : forall F : Type -> Type,
       @Monad.MonadLawsE (ReaderMonad.readerT bool (ITreeDefinition.itree F))
         (@ReaderT.readerT_eq1 bool (ITreeDefinition.itree F) (@ITreeMonad.Eq1_ITree F))
         (@ReaderMonad.Monad_readerT bool (ITreeDefinition.itree F)
            (@ITreeDefinition.Monad_itree F))

@ReaderWriterFold.writer_target_monad
     : forall F : Type -> Type,
       @Monad.MonadLawsE (Basics.Monads.writerT (list nat) (ITreeDefinition.itree F))
         (@WriterT.writerT_eq1 (list nat) (ITreeDefinition.itree F) (@ITreeMonad.Eq1_ITree F))
         (@WriterT.writerT_monad (list nat) (ITreeDefinition.itree F) ReaderWriterFold.logs
            (@ITreeDefinition.Monad_itree F))

@ReaderWriterFold.writer_bind_keeps_order
     : forall F : Type -> Type,
       @Eqit.eq_itree F (list nat * unit) (list nat * unit) (@eq (list nat * unit))
         (@Monad.bind (Basics.Monads.writerT (list nat) (ITreeDefinition.itree F))
            (@WriterT.writerT_monad (list nat) (ITreeDefinition.itree F) ReaderWriterFold.logs
               (@ITreeDefinition.Monad_itree F)) unit unit
            {|
              ITreeDefinition._observe :=
                @ITreeDefinition.RetF F (list nat * unit)
                  (ITreeDefinition.itree F (list nat * unit)) ((1 :: @nil nat)%list, tt)
            |}
            (fun _ : unit =>
             {|
               ITreeDefinition._observe :=
                 @ITreeDefinition.RetF F (list nat * unit)
                   (ITreeDefinition.itree F (list nat * unit)) ((2 :: @nil nat)%list, tt)
             |}))
         {|
           ITreeDefinition._observe :=
             @ITreeDefinition.RetF F (list nat * unit) (ITreeDefinition.itree F (list nat * unit))
               ((1 :: 2 :: @nil nat)%list, tt)
         |}

@ReaderWriterFold.writer_sampling_does_not_log
     : forall (MN F : Type -> Type) (sample : forall X : Type, MN X -> ITreeDefinition.itree F X)
         (X : Type) (m : MN X),
       @WriterFold.writer_sample (list nat) MN (ITreeDefinition.itree F) ReaderWriterFold.logs
         (@ITreeDefinition.Monad_itree F) sample X m =
       @ITreeDefinition.ITree.bind F X (list nat * X) (sample X m)
         (fun x : X =>
          {|
            ITreeDefinition._observe :=
              @ITreeDefinition.RetF F (list nat * X) (ITreeDefinition.itree F (list nat * X))
                (@nil nat, x)
          |})
